values
  ('5-bedroom-detached-duplex-with-pool-ikoyi', '5-Bedroom Fully Detached Duplex with Pool', 'sale', 'detached', 'available', 1250000000, null, false, 'Lagos', 'Lagos', 'Ikoyi', 'Off Bourdillon Road, Ikoyi, Lagos', 5, 6, 7, 4, 1100, 'Certificate of Occupancy (C of O)', 'A contemporary family home on a quiet, tree-lined close minutes from Bourdillon Road. Double-volume living areas open onto a landscaped garden and swimming pool, with a chef''s kitchen, family lounge, cinema room and a two-room BQ. Title has been verified by our land administration team and a current valuation report is available to serious buyers.', array['Swimming pool', '24/7 power', 'Fitted kitchen', 'BQ (boys'' quarters)', 'Cinema room', 'CCTV', 'Borehole', 'Smart home']::text[], array['https://images.unsplash.com/photo-1600585154340-be6161a56a0c', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0', 'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3', 'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9']::text[], true, true, true, '2026-10-11T09:00:00.000Z'),
