  ('3-bedroom-luxury-apartment-oniru-victoria-island', '3-Bedroom Luxury Apartment, Oniru', 'rent', 'apartment', 'available', 18000000, 'year', false, 'Lagos', 'Lagos', 'Victoria Island', 'Oniru Estate, Victoria Island, Lagos', 3, 3, 4, 2, 210, null, 'Serviced three-bedroom apartment in a modern block a short walk from the Oniru beachfront. Floor-to-ceiling glazing, a fitted kitchen, a gym and a rooftop lounge. Service charge covers power, water, security and facility management by our in-house team.', array['Serviced', 'Gym', 'Elevator', 'Rooftop terrace', '24/7 power', 'Ample parking']::text[], array['https://images.unsplash.com/photo-1545324418-cc1a3fa10c00', 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267']::text[], true, true, true, '2026-10-06T09:00:00.000Z'),
